"""Aprobación, cancelación y surtido con identidad, sucursal y revisión del servidor."""
import json,unittest,uuid
import test_backup_import as fixture
class FulfillmentTests(unittest.TestCase):
 def setUp(self):
  self.case=fixture.ModuleBackupTests();self.case.setUp();self.case.import_req([fixture.product(B='SKU00000000001'),fixture.product('SEGUNDO MATERIAL',B='SKU00000000002')]);self.materials=self.case.value('/api/requisiciones/materiales')['materiales'];self.requester=self.user('capture@example.com','requisicion',sucursales=['EJIDOS']);self.warehouse=self.user('warehouse@example.com','almacenista',almacenes=['EJIDOS']);self.aux=self.user('aux@example.com','auxti');self.manager=self.user('manager@example.com','gerente')
 def tearDown(self):self.case.tearDown()
 def user(self,email,role,**access):
  self.case.value('/api/users',{'email':email,'name':role,'role':role,'active':True,'password':self.case.password,**access});return self.case.login(email)
 def create(self):return self.case.value('/api/requisiciones',{'sucursal':'EJIDOS','area':'Produccion Donas','solicitante':'Persona','observaciones':'','claveCliente':uuid.uuid4().hex,'partidas':[{'materialId':m['id'],'cantidad':'3','observaciones':''} for m in self.materials]},self.requester)['documento']
 def change(self,doc,kind,actor,**extra):return self.case.value('/api/requisiciones/cambios',{'tipo':kind,'objetivo':doc['id'],'revision':doc.get('revision',1),'motivo':'Prueba '+kind,**extra},actor)
 def decide(self,change,actor,approved=True):return self.case.value('/api/requisiciones/cambios/'+change['id']+'/resolver',{'aprobar':approved,'comentario':'Decisión autorizada'},actor)
 def test_request_cancellation_and_three_approvers(self):
  for approver in (self.case.admin,self.aux,self.manager):
   for requester in (self.requester,self.warehouse):
    doc=self.create();pending=self.change(doc,'cancelar',requester);self.assertIsNone(pending['documento']);self.assertEqual(pending['cambio']['estado'],'PENDIENTE');self.assertEqual(self.case.value('/api/requisiciones/'+doc['id'])['estado'],'SOLICITADA');result=self.decide(pending['cambio'],approver);self.assertEqual(result['documento']['estado'],'CANCELADA');self.assertEqual(result['documento']['fechaHora'],doc['fechaHora']);self.assertEqual(self.case.call('/api/requisiciones/cambios/'+pending['cambio']['id']+'/resolver',{'aprobar':True,'comentario':'Otra vez'},approver)[0],409)
  self.assertEqual(self.case.value('/api/requisiciones/reportes/general/ejecutar')['resumen']['total'],'0.00')
 def test_approve_then_actual_quantities_and_prints(self):
  doc=self.create();pending=self.change(doc,'aprobar',self.requester);approved=self.decide(pending['cambio'],self.aux)['documento'];self.assertEqual(approved['estado'],'APROBADA');amounts=[{'materialId':m['id'],'cantidadSurtida':q} for m,q in zip(self.materials,('1.25','0'))];surtida=self.change(approved,'surtir',self.warehouse,datos={'partidas':amounts})['documento'];self.assertEqual(surtida['estado'],'SURTIDO');self.assertEqual([p['cantidad'] for p in surtida['partidas']],['3','3']);self.assertEqual([p['cantidadSurtida'] for p in surtida['partidas']],['1.25','0']);self.assertEqual(surtida['numero'],doc['numero']);own=self.case.value('/api/requisiciones/'+doc['id'],actor=self.requester);self.assertIn('surtido',own);self.assertEqual(own['partidas'][0]['cantidadSurtida'],'1.25');self.assertNotIn('costo',json.dumps(own).lower())
  for suffix in ('','?formato=ticket'):
   code,raw,_=self.case.call('/api/requisiciones/'+doc['id']+'/imprimir'+suffix,actor=self.requester);self.assertEqual(code,200);self.assertIn('Surtida' if not suffix else 'Cantidad surtida',raw.decode());self.assertIn('1.25',raw.decode());self.assertNotIn('costo',raw.decode().lower())
  history=self.case.value('/api/requisiciones/'+doc['id']+'/historial',actor=self.requester);self.assertEqual(len(history['versiones']),2);self.assertEqual(history['cambios'][-1]['tipo'],'surtir');backup=self.case.value('/api/respaldos?modulo=requisiciones');self.case.value('/api/respaldos/restaurar/revisar',{'modulo':'requisiciones','respaldo':backup});self.assertEqual(self.case.call('/api/requisiciones/cambios',{'tipo':'surtir','objetivo':doc['id'],'revision':surtida['revision'],'motivo':'Doble entrega','datos':{'partidas':amounts}},self.warehouse)[0],409)
 def test_scope_permissions_invalid_amounts_and_revision(self):
  doc=self.create();payload={'tipo':'surtir','objetivo':doc['id'],'revision':1,'motivo':'Entrega','datos':{'partidas':[{'materialId':m['id'],'cantidadSurtida':'1'} for m in self.materials]}}
  self.assertEqual(self.case.call('/api/requisiciones/cambios',payload,self.requester)[0],403);approved=self.change(doc,'aprobar',self.manager)['documento'];payload['revision']=approved['revision']
  for invalid in ('-1','1000000000','NaN','Infinity','0.0000001',''):
   payload['datos']['partidas'][0]['cantidadSurtida']=invalid;self.assertEqual(self.case.call('/api/requisiciones/cambios',payload,self.warehouse)[0],400)
  payload['datos']['partidas'][0]['cantidadSurtida']='1';payload['datos']['solicitante']='Cambio sin autorizar';self.assertEqual(self.case.call('/api/requisiciones/cambios',payload,self.warehouse)[0],403);payload['datos'].pop('solicitante');other=self.user('other@example.com','requisicion',sucursales=['EJIDOS']);self.assertEqual(self.case.call('/api/requisiciones/cambios',{'tipo':'cancelar','objetivo':doc['id'],'revision':approved['revision'],'motivo':'Ajena'},other)[0],403)
  wrong=self.user('wrong@example.com','almacenista',almacenes=['SAN PABLO']);self.assertEqual(self.case.call('/api/requisiciones/cambios',payload,wrong)[0],403);payload['revision']=1;self.assertEqual(self.case.call('/api/requisiciones/cambios',payload,self.warehouse)[0],409)
 def test_pending_decisions_revalidate_and_rejection_does_not_cancel(self):
  doc=self.create();pending=self.change(doc,'cancelar',self.requester)['cambio'];self.decide(pending,self.manager,False);self.assertEqual(self.case.value('/api/requisiciones/'+doc['id'])['estado'],'SOLICITADA');pending=self.change(doc,'cancelar',self.requester)['cambio'];self.case.value('/api/users',{'email':'capture@example.com','name':'Persona','role':'requisicion','active':True,'sucursales':['SAN PABLO']});self.assertEqual(self.case.call('/api/requisiciones/cambios/'+pending['id']+'/resolver',{'aprobar':True,'comentario':'Perdió acceso'},self.aux)[0],409)
 def test_direct_fulfillment_all_roles_correction_and_report_totals(self):
  for operator in (self.warehouse,self.case.admin,self.aux,self.manager):
   doc=self.create();pending=self.change(doc,'aprobar',self.requester)['cambio'];actual=[{'materialId':m['id'],'cantidadSurtida':q} for m,q in zip(self.materials,('1.25','0'))];done=self.change(doc,'surtir',operator,datos={'partidas':actual})['documento'];self.assertEqual(done['estado'],'SURTIDO');self.assertIn('aprobacion',done);self.assertEqual(next(c for c in self.case.value('/api/requisiciones/cambios',actor=self.requester)['cambios'] if c['id']==pending['id'])['estado'],'APROBADA')
  config=self.case.value('/api/requisiciones/reportes/general/ejecutar')['configuracion'];config['folios']=done['numero'];config['impuestos']=[{'nombre':'IVA','tasa':'16'}];report=lambda:self.case.value('/api/requisiciones/reportes/vista-previa',config);before=report();self.assertEqual(before['resumen']['totalRequisitado'],'69.60');self.assertEqual(before['resumen']['totalSurtido'],'14.50');self.assertEqual(before['resumen']['total'],'14.50');self.assertEqual(before['resumen']['cantidadesPorUnidad'],[{'unidad':'KILO','requisitado':'6','surtido':'1.25'}])
  actual[0]['cantidadSurtida']='2';change=self.change(done,'corregir_surtido',self.warehouse,datos={'partidas':actual,'area':done['area'],'solicitante':'Nombre corregido','observaciones':'Entrega corregida'});self.assertIsNone(change['documento']);self.assertEqual(report()['resumen']['totalSurtido'],'14.50');self.assertEqual(self.case.call('/api/requisiciones/cambios/'+change['cambio']['id']+'/resolver',{'aprobar':True,'comentario':'Intento'},self.warehouse)[0],403);updated=self.decide(change['cambio'],self.manager)['documento'];self.assertEqual(updated['estado'],'SURTIDO');self.assertEqual(updated['solicitante'],'Nombre corregido');self.assertEqual(updated['fechaHora'],done['fechaHora']);self.assertEqual(report()['resumen']['totalSurtido'],'23.20')
  for approver in (self.case.admin,self.aux,self.manager):
   actual[0]['cantidadSurtida']='1';updated=self.change(updated,'corregir_surtido',approver,datos={'partidas':actual})['documento'];self.assertEqual(updated['estado'],'SURTIDO');self.assertEqual(updated['partidas'][0]['cantidadSurtida'],'1')
  for fmt in ('xlsx','pdf'):
   status,body,_=self.case.call('/api/requisiciones/reportes/exportar/'+fmt,{'configuracion':config});self.assertEqual(status,200,body[:200]);self.assertTrue(body.startswith(b'PK' if fmt=='xlsx' else b'%PDF-'))
  self.case.value('/api/respaldos/restaurar/revisar',{'modulo':'requisiciones','respaldo':self.case.value('/api/respaldos?modulo=requisiciones')})
 def test_unsupplied_is_zero_and_units_are_separate(self):
  self.case.import_req([fixture.product(B='SKU00000000001'),fixture.product('SEGUNDO MATERIAL',B='SKU00000000002',N='PIEZA')]);cost=next(c for c in self.case.value('/api/requisiciones/costos')['costos'] if c['materialId']==self.materials[1]['id']);self.case.value('/api/requisiciones/costos',{'materialId':cost['materialId'],'revision':cost['revision'],'costoEntrega':'10','precioCompra':'10','factor':'1','unidadCompra':'PIEZA'},method='PUT');doc=self.create();r=self.case.value('/api/requisiciones/reportes/general/ejecutar');self.assertEqual(r['resumen']['totalSurtido'],'0.00');self.assertEqual(r['resumen']['totalRequisitado'],'60.00');self.assertEqual(len(r['resumen']['cantidadesPorUnidad']),2)
  done=self.change(doc,'surtir',self.warehouse,datos={'partidas':[{'materialId':m['id'],'cantidadSurtida':'1'} for m in self.materials]})['documento'];config=r['configuracion'];config['agrupacion']='unidad';r=self.case.value('/api/requisiciones/reportes/vista-previa',config);self.assertEqual({q['unidad'] for q in r['resumen']['cantidadesPorUnidad']},{'KILO','PIEZA'});from reporte_export import select_detail
  selected=select_detail(r,{key:r['grupos'][0][key] for key in ('grupo','materialId','unidad')});self.assertEqual(len(selected['resumen']['cantidadesPorUnidad']),1);self.assertEqual(selected['resumen']['totalRequisitado'],'30.00');self.assertEqual(selected['resumen']['totalSurtido'],'10.00')
if __name__=='__main__':unittest.main()
